var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Modifica in sicurezza la configurazione del touchscreen KlipperScreen della stampante, poi riavvia KlipperScreen per applicarla. Ogni salvataggio viene prima sottoposto a backup.`}},selector:{title:{t:0,b:{t:2,i:[{t:3}],s:`Touchscreen`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Scegli quale interfaccia viene eseguita sul display della stampante.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Aggiorna`}},active:{t:0,b:{t:2,i:[{t:3}],s:`In esecuzione`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`All'avvio`}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Non installata`}},use:{t:0,b:{t:2,i:[{t:3}],s:`Usa`}},switching:{t:0,b:{t:2,i:[{t:3}],s:`Cambio in corso…`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Imposta anche come predefinita all'avvio`}},installedNotManageable:{t:0,b:{t:2,i:[{t:3}],s:`Installato`}},notManageableHint:{t:0,b:{t:2,i:[{t:3}],s:`Installato, ma non commutabile da qui (nessun servizio systemd).`}}},touchPanel:{title:{t:0,b:{t:2,i:[{t:3}],s:`Controlli FilaMind`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Esegui i controlli e i test di FilaMind direttamente dallo schermo.`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Aiuto`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Informazioni su KlipperScreen Studio`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Come leggere`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Modifica il testo di configurazione qui sotto (oppure lascialo invariato).`}},{t:0,b:{t:2,i:[{t:3}],s:`Salva: il file attuale viene prima sottoposto a backup e il salvataggio viene rifiutato mentre la stampante è occupata.`}},{t:0,b:{t:2,i:[{t:3}],s:`Riavvia KlipperScreen per applicare la modifica sullo schermo fisico.`}},{t:0,b:{t:2,i:[{t:3}],s:`Le righe usano terminatori UNIX (LF), applicati automaticamente al salvataggio.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossario`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Definizioni rapide dei termini di KlipperScreen usati qui.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la scheda Config?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Il file KlipperScreen.conf grezzo. Modifica qualsiasi impostazione a mano; il salvataggio esegue prima il backup del file, viene rifiutato mentre la stampante è occupata e avvisa se il file è cambiato sullo schermo da quando lo hai caricato. La maggior parte delle persone usa invece le schede Impostazioni / Menu / Temi.`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la scheda Impostazioni?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Le opzioni [main] più usate sotto forma di modulo: tema, lingua, sospensione dello schermo, dimensione del carattere e interruttori. Precompilate dalla configurazione attiva; vengono scritte solo le opzioni che modifichi. Riavvia per applicare.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la scheda Menu?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Progetta le griglie di pulsanti del touchscreen. Ogni albero (__main è la griglia principale, __print la schermata di stampa) elenca i suoi pulsanti; aggiungili, rinominali, riordinali e annidali, e imposta ognuno per aprire un sotto-menu, aprire una schermata integrata o eseguire G-code.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la scheda Temi?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Crea un tema KlipperScreen: scegli un colore per ogni token della palette e un raggio degli angoli, osserva l'anteprima dal vivo, poi crealo e applicalo allo schermo. L'anteprima è approssimativa: lo schermo reale viene renderizzato in GTK.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cos'è la scheda Kiosk?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Metti FilaMind Flow stesso sul touchscreen come browser a schermo intero: controllo totale di ciò che lo schermo mostra. È uno scambio reversibile con KlipperScreen (temporaneo per impostazione predefinita; un riavvio ripristina KlipperScreen). Richiede l'installer una tantum sull'host della stampante.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`L'interfaccia touchscreen che gira su un piccolo display collegato alla stampante, separata da questo pannello web.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Un aspetto di KlipperScreen: colori, icone e raggio degli angoli. Risiede in una cartella styles/<name> sull'host; solo estetico (non può cambiare il layout).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`Menu (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Le griglie di pulsanti che KlipperScreen mostra. __main è la schermata principale, __print la schermata mostrata durante la stampa, __splashscreen la schermata di avvio.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`Pannello`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Una schermata integrata di KlipperScreen che un pulsante può aprire (movimento, temperatura, estrusione, bed mesh, …). I loro contenuti interni sono fissati da KlipperScreen.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`Blocco generato automaticamente (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`La sezione che KlipperScreen scrive per sé in fondo al file conf, dopo il marcatore #~#. FilaMind non la modifica mai: solo le tue impostazioni sopra di essa.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Eseguire un browser a schermo intero sul touchscreen al posto di KlipperScreen, così lo schermo mostra FilaMind Flow. Completamente reversibile.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`Ricerca di KlipperScreen in corso…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen non è stato rilevato su questa stampante (nessun KlipperScreen.conf e non segnalato da Moonraker). Installa KlipperScreen per usare questo strumento.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen rilevato`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Lingua`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker non può riavviare KlipperScreen automaticamente: riavvialo manualmente dopo il salvataggio.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Lettura di KlipperScreen.conf…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`Ricarica`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Salva config`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Salvataggio…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`Salvato (backup eseguito)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Modifiche non salvate`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`Rifiutato mentre la stampante è occupata: riprova quando è inattiva.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf è cambiato su disco da quando è stato caricato (probabilmente modificato sullo schermo). Ricarica prima di salvare per non sovrascrivere quella modifica.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`Config`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Impostazioni`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`Menu`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`Temi`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Caricamento impostazioni…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Le opzioni di visualizzazione di KlipperScreen più usate sotto forma di modulo. Vengono scritte solo le opzioni che modifichi: tutto il resto mantiene il valore attuale. Riavvia per applicare.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`Solo le impostazioni che modifichi qui vengono scritte in KlipperScreen.conf.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Salva impostazioni`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Salvato: riavvia KlipperScreen per applicare.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`Lascia non impostato (predefinito)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`Mai (sempre acceso)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`Piccolo`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`Medio`}},large:{t:0,b:{t:2,i:[{t:3}],s:`Grande`}},max:{t:0,b:{t:2,i:[{t:3}],s:`Massimo`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Lingua`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`Sospensione schermo dopo`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`Dimensione carattere`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`Orologio a 24 ore`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`Usa DPMS per spegnere lo schermo`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`Mostra il cursore del mouse`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`Conferma prima dell'arresto di emergenza`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`Mostra la potenza del riscaldatore %`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi automaticamente i pop-up`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Verifica dello schermo…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Metti FilaMind Flow stesso sul touchscreen come browser a schermo intero: controllo totale di ciò che lo schermo mostra. Si scambia con KlipperScreen: avviarne uno ferma l'altro.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Schermo ora`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk FilaMind`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Nessuno in esecuzione`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk non ancora installato`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`Esegui questo una volta sull'host della stampante (installa un browser a schermo intero + il servizio kiosk):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Rendilo predefinito all'avvio (altrimenti lo scambio è temporaneo: un riavvio ripristina l'altro).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`Temporaneo per impostazione predefinita: un riavvio riporta l'altro. Se lo schermo diventa nero, via SSH esegui: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Passa a FilaMind`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`Ripristina KlipperScreen`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Aggiorna`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`Mettere FilaMind sullo schermo?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`Ripristinare KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Questo ferma un servizio dello schermo e avvia l'altro. Non influisce su una stampa attiva, ma il touchscreen diventerà nero per alcuni secondi durante il cambio.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Procedi`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind sta prendendo il controllo dello schermo: dovrebbe comparire in pochi secondi.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen sta tornando: lo schermo dovrebbe riapparire a breve.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Caricamento menu…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Progetta ciò che il touchscreen mostra: i pulsanti di ogni menu, il loro ordine e cosa fa ciascuno. La griglia della schermata principale è l'albero __main; la schermata di stampa è __print.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`Aggiungi pulsante`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Ancora nessun elemento: aggiungine uno.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`Sposta su`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Sposta giù`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`Aggiungi sotto-elemento`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Elimina`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Nome`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`Icona`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Azione`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`Apri un sotto-menu`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`Apri una schermata`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`Esegui G-code`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`Schermata`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Mostra se`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Salva menu`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`Nuovo pulsante`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Menu salvati: riavvia KlipperScreen per vederli.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Caricamento temi…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`Palette`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`Raggio degli angoli`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`Anteprima dal vivo`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`Pulsante`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`avviso`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`Anteprima approssimativa: lo schermo reale viene renderizzato con GTK; sono previste lievi differenze.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Nome del nuovo tema`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`Crea e applica`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`Crea soltanto`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`Temi installati`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Applica`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Elimina tema`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`Creato qui`}},created:{t:0,b:{t:2,i:[{t:3}],s:`Tema creato. Applicalo dall'elenco, poi riavvia.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Tema impostato: riavvia KlipperScreen per vederlo.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`Stampante`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`Riavvia KlipperScreen`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Riavvio…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen si sta riavviando: lo schermo si ricaricherà a breve.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Riavviare KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Questo riavvia il servizio del touchscreen per applicare le modifiche. Non influisce su una stampa attiva, ma lo schermo diventa nero per alcuni secondi.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Riavvia`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annulla`}}},section:{touch:{t:0,b:{t:2,i:[{t:3}],s:`Interfaccia touch`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},tools:{t:0,b:{t:2,i:[{t:3}],s:`Strumenti e test`}}}}};export{e as default};